<script setup>
import { computed, ref } from 'vue';
import DesktopSwitch from './DesktopSwitch.vue';
import DoubaoQuota from './DoubaoQuota.vue';
import { Alert as AAlert, Button as AButton, Input as AInput, Table as ATable, TableColumn as ATableColumn, Progress as AProgress, Empty as AEmpty, Tooltip as ATooltip, Modal as AModal, Select as ASelect, Option as AOption } from '@arco-design/web-vue';
import { IconSearch, IconFilter, IconRefresh, IconPlus, IconCheck, IconClockCircle, IconArrowRight, IconCalendar } from '@arco-design/web-vue/es/icon';
import { canCheckin, checkinState, accountEdition, accountCredits, formatHour, formatNumber } from '../useAccounts';

const props = defineProps({ model: Object });
const sessionOnly = computed(() => props.model.provider === 'antigravity');
const doubao = computed(() => props.model.provider === 'doubao');
const refreshLabel = computed(() => sessionOnly.value ? '刷新授权' : doubao.value ? '刷新额度' : '刷新积分');
const noCheckin = computed(() => ['antigravity', 'loomy'].includes(props.model.provider));
const localLoomy = computed(() => props.model.provider === 'loomy');
const readingLoomy = computed(() => localLoomy.value && props.model.busy.has('loomy-import'));
const emptyDescription = computed(() => props.model.accounts.length ? '没有匹配的账号' : localLoomy.value ? readingLoomy.value ? '正在读取本机登录配置…' : '请先在本机 Loomy 桌面端登录，再点击「重新读取」' : '还没有账号');
const emit = defineEmits(['remark', 'remove', 'navigate', 'switch']);
const query = ref(''), filter = ref('all'), expiryVisible = ref(false), filtersVisible = ref(false);
const quiet = promise => promise?.catch(() => {});
const filters = computed(() => [
  { id: 'all', text: '全部', count: props.model.accounts.length },
  ...(noCheckin.value ? [] : [{ id: 'pending', text: '待签到', count: props.model.pending.length },
  { id: 'signed', text: '已签到', count: props.model.signed.length }]),
  { id: 'disabled', text: '已停用', count: props.model.accounts.filter(a => a.disabled).length },
]);
const visible = computed(() => props.model.accounts.filter(a => {
  const text = [a.uid, a.nickname, props.model.remarks[a.uid]].join(' ').toLowerCase();
  return text.includes(query.value.trim().toLowerCase()) && (filter.value === 'all' || filter.value === 'pending' && canCheckin(a) && !a.checkin_done || filter.value === 'signed' && canCheckin(a) && a.checkin_done || filter.value === 'disabled' && a.disabled);
}));
const expirySoon = computed(() => props.model.expiryEntries.filter(e => new Date(e.expires_at || e.date).getTime() - props.model.now < 30 * 86400000));
const ratio = a => a.credits_total > 0 ? Math.min(1, Math.max(0, a.credits / a.credits_total)) : 0;
function daysLeft(entry) { return Math.max(0, Math.ceil((new Date(entry.expires_at || entry.date).getTime() - props.model.now) / 86400000)); }
function expiryDate(entry) { return new Date(entry.expires_at || entry.date).toLocaleDateString('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit' }); }
</script>

<template>
  <section class="account-view">
    <header class="page-heading">
      <div class="page-toolbar"><slot name="platform-switcher" /><div class="heading-actions"><a-button :loading="model.busy.has('balances')" :disabled="!model.accounts.length" @click="quiet(model.refreshBalances())"><template #icon><icon-refresh /></template>{{ refreshLabel }}</a-button><a-button v-if="!noCheckin" :loading="model.busy.has('checkin-all')" :disabled="!model.pending.length" @click="quiet(model.checkinAll())"><template #icon><icon-check /></template>全部签到</a-button><a-button v-if="localLoomy" :loading="readingLoomy" :disabled="!model.connected" @click="quiet(model.importLoomyLocal())"><template #icon><icon-refresh /></template>重新读取</a-button><a-button v-else type="primary" @click="model.openAdd()"><template #icon><icon-plus /></template>添加账号</a-button></div></div>
      <div class="mobile-bulk-actions"><a-tooltip :content="refreshLabel"><a-button :aria-label="refreshLabel" :loading="model.busy.has('balances')" :disabled="!model.accounts.length" @click="quiet(model.refreshBalances())"><template #icon><icon-refresh /></template></a-button></a-tooltip><a-tooltip v-if="!noCheckin" content="全部签到"><a-button aria-label="全部签到" :loading="model.busy.has('checkin-all')" :disabled="!model.pending.length" @click="quiet(model.checkinAll())"><template #icon><icon-check /></template></a-button></a-tooltip><a-tooltip v-if="localLoomy" content="重新读取本机配置"><a-button aria-label="重新读取本机配置" :loading="readingLoomy" :disabled="!model.connected" @click="quiet(model.importLoomyLocal())"><template #icon><icon-refresh /></template></a-button></a-tooltip></div>
    </header>

    <div class="stats-band" :style="sessionOnly ? { gridTemplateColumns: 'repeat(3, minmax(0, 1fr))' } : noCheckin ? { gridTemplateColumns: 'repeat(2, minmax(0, 1fr))' } : undefined">
      <div class="metric"><span class="metric-label"><span class="desktop-text">账号总数</span><span class="mobile-text">账号</span></span><strong>{{ formatNumber(model.accounts.length) }}</strong><small>{{ model.providerName }}</small></div>
      <template v-if="sessionOnly"><div class="metric"><span class="metric-label">已启用</span><strong>{{ model.accounts.filter(a => !a.disabled).length }}</strong></div><div class="metric"><span class="metric-label">自动续期</span><strong>{{ model.accounts.filter(a => a.has_refresh).length }}</strong></div></template>
      <div v-if="!noCheckin" class="metric"><span class="metric-label"><span class="desktop-text">今日已签到</span><span class="mobile-text">已签到</span></span><strong class="accent-text">{{ formatNumber(model.signed.length) }}</strong><small>共 {{ model.eligible.length }} 个可签到账号</small></div>
      <div v-if="!noCheckin" class="metric"><span class="metric-label">待签到</span><strong class="warning-text">{{ formatNumber(model.pending.length) }}</strong><small>{{ model.nextRun ? `下次签到 ${model.nextRun.day} ${model.nextRun.time}` : '自动签到已关闭' }}</small></div>
      <div v-if="!sessionOnly" class="metric"><span class="metric-label"><span class="desktop-text">{{ doubao ? '活动剩余额度' : '剩余积分' }}</span><span class="mobile-text">{{ doubao ? '活动额度' : '积分' }}</span></span><strong :class="{ 'compact-value': formatNumber(model.credits).length > 5 }" :title="formatNumber(model.credits)">{{ model.accounts.length && model.unknownBalances === model.accounts.length ? '--' : formatNumber(model.credits) }}</strong><small v-if="model.unknownBalances">{{ model.unknownBalances }} 个账号尚未获取余额</small><small v-else-if="doubao">活动赠送额度合计 {{ formatNumber(model.totalCredits) }} · 订阅周期额度见账号明细</small><small v-else>总额 {{ model.totalCredits ? formatNumber(model.totalCredits) : '--' }}<template v-if="model.totalCredits"> · 剩余 {{ Math.round(model.credits / model.totalCredits * 100) }}%</template></small></div>
    </div>

    <p v-if="model.provider === 'qoder'" class="qoder-reward-note">每日奖励于北京时间 10:00 更新，每轮 100 Credits，有效期 30 天。</p>
    <p v-else-if="model.provider === 'loomy'" class="qoder-reward-note">{{ readingLoomy ? '正在读取本机 Loomy 登录配置…' : '选择 Loomy 时自动读取本机登录配置，无需添加账号。每日积分由桌面端自动发放，面板仅查询与展示积分余额。' }}</p>

    <a-alert v-if="localLoomy && model.loomyLocalError" type="warning" class="connection-alert">{{ model.loomyLocalError }}</a-alert>

    <div class="account-toolbar">
      <a-input v-model="query" allow-clear placeholder="搜索账号、昵称或备注" :input-attrs="{ 'aria-label': '搜索账号' }" class="account-search"><template #prefix><icon-search /></template></a-input>
      <div class="filter-tabs" role="group" aria-label="筛选账号"><button v-for="item in filters" :key="item.id" :class="{ active: filter === item.id }" :aria-pressed="filter === item.id" @click="filter = item.id">{{ item.text }} <span>{{ item.count }}</span></button></div>
      <span class="result-count">{{ visible.length }} / {{ model.accounts.length }} 个账号</span>
      <a-tooltip content="筛选账号"><a-button class="mobile-filter" aria-label="筛选账号" @click="filtersVisible = true"><template #icon><icon-filter /></template></a-button></a-tooltip>
    </div>

    <div class="desktop-account-table">
      <a-table :data="visible" row-key="uid" :pagination="false" :bordered="false" :loading="model.loading || readingLoomy" :scroll="{ x: 1050 }" :hoverable="false">
        <template #columns>
          <a-table-column title="账号" :width="300"><template #cell="{ record }"><div class="account-identity"><span :class="['account-avatar', { disabled: record.disabled }]">{{ model.accountName(record).slice(0, 1) }}</span><div class="identity-text"><strong>{{ model.accountName(record) }}</strong><small>{{ record.uid }}</small><a-tooltip v-if="record.last_error" :content="record.last_error"><div class="account-warning">{{ record.last_error }}</div></a-tooltip></div></div></template></a-table-column>
          <a-table-column title="状态" :width="112"><template #cell="{ record }"><span :class="['account-status', { disabled: record.disabled, 'warning-text': record.last_error && !record.disabled }]"><i class="status-dot" />{{ record.disabled ? '已停用' : record.last_error ? '需处理' : '正常' }}</span><small class="realm-name">{{ accountEdition(record) }}</small></template></a-table-column>
          <a-table-column v-if="!sessionOnly" :title="doubao ? '订阅与额度' : '剩余积分'" :width="doubao ? 280 : 150"><template #cell="{ record }"><DoubaoQuota v-if="doubao" :account="record" /><template v-else><div :class="['credit-amount', { disabled: record.disabled }]"><b>{{ accountCredits(record) }}</b><small v-if="record.credits_total"> / {{ formatNumber(record.credits_total) }}</small></div><small v-if="record.provider === 'loomy' && record.balance_known" class="daily-balance-note">每日赠送 {{ formatNumber(record.daily_balance) }}</small><a-progress v-if="record.credits_total" :percent="ratio(record)" :show-text="false" size="small" :stroke-width="3" :color="record.disabled ? 'var(--muted)' : 'var(--accent)'" /></template></template></a-table-column>
          <a-table-column v-if="!noCheckin" :title="model.provider === 'qoder' ? '本轮奖励' : '今日签到'" :width="124"><template #cell="{ record }"><span :class="['checkin-tag', checkinState(record).kind]"><icon-check v-if="record.checkin_done" /><icon-clock-circle v-else-if="canCheckin(record)" />{{ checkinState(record).text }}</span></template></a-table-column>
          <a-table-column title="操作" :width="model.provider === 'trae' ? 360 : 300" align="right"><template #cell="{ record }"><div class="row-actions"><DesktopSwitch :model="model" :account="record" @switch="emit('switch', $event)" /><a-button v-if="canCheckin(record) && !record.checkin_done" type="text" size="mini" class="checkin-action" :loading="model.busy.has(record.uid + ':checkin')" @click="quiet(model.accountAction(record, 'checkin'))">签到</a-button><template v-if="['trae', 'qoder', 'minimax', 'loomy', 'antigravity', 'doubao'].includes(record.provider)"><a-button type="text" size="mini" :loading="model.busy.has(record.uid + ':balance')" @click="quiet(model.accountAction(record, 'balance'))">刷新</a-button><a-button v-if="record.provider !== 'loomy'" type="text" size="mini" @click="record.provider === 'doubao' ? model.updateDoubao(record) : record.provider === 'antigravity' ? model.updateAntigravity(record) : record.provider === 'qoder' ? model.updateQoder(record) : record.provider === 'minimax' ? model.updateMiniMax(record) : model.updateTrae(record)">{{ ['antigravity', 'doubao'].includes(record.provider) ? '重新授权' : '凭证' }}</a-button></template><a-button type="text" size="mini" @click="emit('remark', record)">备注</a-button><a-button v-if="model.capabilities?.gateway && !['trae', 'qoder', 'minimax', 'loomy', 'antigravity', 'doubao'].includes(record.provider)" type="text" size="mini" :loading="model.busy.has(record.uid + ':' + (record.paused ? 'resume' : 'pause'))" @click="quiet(model.accountAction(record, record.paused ? 'resume' : 'pause'))">{{ record.paused ? '恢复选号' : '暂停选号' }}</a-button><a-button type="text" size="mini" :loading="model.busy.has(record.uid + ':' + (record.disabled ? 'revive' : 'disable'))" @click="quiet(model.accountAction(record, record.disabled ? 'revive' : 'disable'))">{{ record.disabled ? '启用' : '停用' }}</a-button><a-button type="text" status="danger" size="mini" @click="emit('remove', record)">移除</a-button></div></template></a-table-column>
        </template>
        <template #empty><a-empty :description="emptyDescription"><a-button v-if="!model.accounts.length && !localLoomy" type="primary" @click="model.openAdd()"><template #icon><icon-plus /></template>添加账号</a-button></a-empty></template>
      </a-table>
      <footer v-if="!noCheckin" class="table-footer"><span><i class="status-dot" />{{ model.schedule?.checkin_enabled ? '自动签到已开启' : '自动签到已关闭' }} · 北京时间 {{ model.effectiveHours.map(formatHour).join(' / ') }}<template v-if="model.nextRun"> · 下次 {{ model.nextRun.day }} {{ model.nextRun.time }}</template></span><span>积分在签到或手动刷新后更新</span></footer>
    </div>

    <div class="mobile-account-list">
      <article v-for="account in visible" :key="account.uid" class="mobile-account">
        <div class="mobile-account-top"><div class="account-identity"><span :class="['account-avatar', { disabled: account.disabled }]">{{ model.accountName(account).slice(0, 1) }}</span><div class="identity-text"><strong>{{ model.accountName(account) }}</strong><small>{{ account.uid }}</small></div></div><span :class="['account-status', { disabled: account.disabled }]"><i class="status-dot" />{{ account.disabled ? '已停用' : '正常' }}</span></div>
        <div v-if="!sessionOnly" class="mobile-account-balance"><DoubaoQuota v-if="doubao" :account="account" /><div v-else><small>剩余积分</small><div class="credit-amount"><b>{{ accountCredits(account) }}</b><small v-if="account.credits_total"> / {{ formatNumber(account.credits_total) }}</small></div><small v-if="account.provider === 'loomy' && account.balance_known" class="daily-balance-note">每日赠送 {{ formatNumber(account.daily_balance) }}</small></div><span v-if="!noCheckin" :class="['checkin-tag', checkinState(account).kind]"><icon-check v-if="account.checkin_done" /><icon-clock-circle v-else-if="canCheckin(account)" />{{ checkinState(account).text }}</span></div>
        <p v-if="account.last_error" class="account-warning" :title="account.last_error">{{ account.last_error }}</p>
        <div v-if="!['minimax', 'loomy', 'antigravity', 'doubao'].includes(account.provider)" class="mobile-desktop-action"><DesktopSwitch :model="model" :account="account" @switch="emit('switch', $event)" /></div><footer class="mobile-account-footer"><span class="realm-pill">{{ accountEdition(account) }}</span><div class="row-actions"><a-button v-if="canCheckin(account) && !account.checkin_done" type="text" size="mini" :loading="model.busy.has(account.uid + ':checkin')" @click="quiet(model.accountAction(account, 'checkin'))">签到</a-button><template v-if="['trae', 'qoder', 'minimax', 'loomy', 'antigravity', 'doubao'].includes(account.provider)"><a-button type="text" size="mini" :loading="model.busy.has(account.uid + ':balance')" @click="quiet(model.accountAction(account, 'balance'))">刷新</a-button><a-button v-if="account.provider !== 'loomy'" type="text" size="mini" @click="account.provider === 'doubao' ? model.updateDoubao(account) : account.provider === 'antigravity' ? model.updateAntigravity(account) : account.provider === 'qoder' ? model.updateQoder(account) : account.provider === 'minimax' ? model.updateMiniMax(account) : model.updateTrae(account)">{{ ['antigravity', 'doubao'].includes(account.provider) ? '重新授权' : '凭证' }}</a-button></template><a-button type="text" size="mini" @click="emit('remark', account)">备注</a-button><a-button v-if="model.capabilities?.gateway && !['trae', 'qoder', 'minimax', 'loomy', 'antigravity', 'doubao'].includes(account.provider)" type="text" size="mini" :loading="model.busy.has(account.uid + ':' + (account.paused ? 'resume' : 'pause'))" @click="quiet(model.accountAction(account, account.paused ? 'resume' : 'pause'))">{{ account.paused ? '恢复选号' : '暂停选号' }}</a-button><a-button type="text" size="mini" :loading="model.busy.has(account.uid + ':' + (account.disabled ? 'revive' : 'disable'))" @click="quiet(model.accountAction(account, account.disabled ? 'revive' : 'disable'))">{{ account.disabled ? '启用' : '停用' }}</a-button><a-button type="text" status="danger" size="mini" @click="emit('remove', account)">移除</a-button></div></footer>
      </article>
      <a-empty v-if="!visible.length && !model.loading" :description="emptyDescription"><a-button v-if="!model.accounts.length && !localLoomy" type="primary" @click="model.openAdd()">添加账号</a-button></a-empty>
      <p v-if="!noCheckin" class="mobile-schedule-line"><i class="status-dot" />{{ model.schedule?.checkin_enabled ? '自动签到' : '自动签到已关闭' }} {{ model.effectiveHours.map(formatHour).join(' / ') }}<template v-if="model.nextRun"> · 下次 {{ model.nextRun.day }} {{ model.nextRun.time }}</template></p>
    </div>

    <div v-if="!sessionOnly" class="account-insights">
      <section v-if="!noCheckin" class="schedule-insight"><div class="inline-between"><h2>自动签到 <span :class="['checkin-tag', model.schedule?.checkin_enabled ? 'success' : 'muted']">{{ model.schedule?.checkin_enabled ? '运行中' : '已关闭' }}</span></h2><a-button type="text" size="mini" @click="emit('navigate', 'settings')">签到设置<icon-arrow-right /></a-button></div><div class="insight-times"><template v-for="(hour, index) in model.effectiveHours" :key="hour"><span v-if="index" class="time-separator">·</span><b>{{ formatHour(hour) }}</b></template><small>每天 · 北京时间</small></div><div class="schedule-pills"><span v-for="hour in model.effectiveHours" :key="hour"><icon-calendar />{{ formatHour(hour) }}</span></div><p><icon-clock-circle />{{ model.nextRun ? `下次运行 ${model.nextRun.day} ${model.nextRun.time} · 还有 ${model.nextRun.remaining}` : '当前仅支持手动签到' }}</p></section>
      <section v-if="model.provider === 'qoder'" class="expiry-insight"><div class="inline-between"><h2>奖励领取 <small>Qoder 国内版</small></h2></div><div class="expiry-row"><span>支持自动续期</span><b>{{ model.accounts.filter(a => a.has_refresh).length }} 个账号</b></div><p>每轮窗口为当日 10:00 至次日 10:00。早于 10 点的签到时刻顺延至 10:00。</p><a class="qoder-rules" href="https://docs.qoder.cn/events/100credits" target="_blank" rel="noopener noreferrer">官方活动规则</a></section>
      <section v-else-if="model.provider === 'minimax'" class="expiry-insight"><div class="inline-between"><h2>接入状态 <small>MiniMax 国内版</small></h2></div><div class="expiry-row"><span>已添加账号</span><b>{{ model.accounts.length }} 个</b></div><div class="expiry-row"><span>支持自动续期</span><b>{{ model.accounts.filter(a => a.has_refresh).length }} 个账号</b></div><p>浏览器授权与桌面端同流程；令牌临期自动续期，签到在共用时刻执行。</p></section>
      <section v-else-if="model.provider === 'loomy'" class="expiry-insight"><div class="inline-between"><h2>接入状态 <small>Loomy 国内版</small></h2></div><div class="expiry-row"><span>已添加账号</span><b>{{ model.accounts.length }} 个</b></div><div class="expiry-row"><span>今日已得积分</span><b>{{ formatNumber(model.accounts.reduce((sum, a) => sum + Number(a.today_earned || 0), 0)) }} 分</b></div><p>选择 Loomy 时自动读取本机桌面端的登录配置；重新登录或更换账号后可点击「重新读取」。每日积分由桌面端自动发放，面板仅查询与展示积分余额。</p></section>
      <section v-else-if="model.provider === 'trae'" class="expiry-insight"><div class="inline-between"><h2>登录状态 <small>Trae 国内版</small></h2></div><div class="expiry-row"><span>支持自动续期</span><b>{{ model.accounts.filter(a => a.has_session || a.has_oauth).length }} 个账号</b></div><div class="expiry-row"><span>需要检查凭证或请求结果</span><b>{{ model.accounts.filter(a => a.last_error).length }} 个账号</b></div><p>登录失效后，使用「凭证」重新授权或更新 Session。</p></section>
      <section v-else-if="model.provider === 'doubao'" class="expiry-insight"><div class="inline-between"><h2>额度状态 <small>豆包</small></h2></div><div class="expiry-row"><span>已获取余额</span><b>{{ model.accounts.filter(a => a.balance_known).length }} 个账号</b></div><div class="expiry-row"><span>查询需重试</span><b>{{ model.accounts.filter(a => a.last_error).length }} 个账号</b></div><p>活动赠送额度与近 7 天等订阅额度分别展示。网页授权后自动查询，也可点击「刷新额度」；查询失败时保留上次成功结果和时间。</p></section>
      <section v-else class="expiry-insight"><div class="inline-between"><h2>积分到期 <small>按到期先后扣减</small></h2><a-button v-if="model.expiryEntries.length" type="text" size="mini" @click="expiryVisible = true">查看全部<icon-arrow-right /></a-button></div><div v-if="!model.expiryEntries.length" class="inline-empty">暂无积分到期记录</div><div v-for="entry in model.expiryEntries.slice(0, 2)" :key="entry.uid + entry.date + entry.expires_at" class="expiry-row"><time>{{ expiryDate(entry) }}</time><span>{{ entry.name }}</span><b>{{ formatNumber(entry.remain) }} 分</b><small>{{ daysLeft(entry) }} 天后</small></div><p v-if="expirySoon.length">30 天内共 {{ formatNumber(expirySoon.reduce((sum, entry) => sum + Number(entry.remain), 0)) }} 分到期</p></section>
    </div>
    <a-modal v-model:visible="expiryVisible" title="积分到期" :footer="false" width="560px" :unmount-on-close="true"><div class="all-expiry"><div v-for="entry in model.expiryEntries" :key="entry.uid + entry.date + entry.expires_at" class="expiry-row"><time>{{ expiryDate(entry) }}</time><span>{{ entry.name }}</span><b>{{ formatNumber(entry.remain) }} 分</b><small>{{ daysLeft(entry) }} 天后</small></div></div></a-modal>
    <a-modal v-model:visible="filtersVisible" title="筛选账号" :footer="false" width="360px"><a-select v-model="filter" aria-label="筛选账号状态" @change="filtersVisible = false"><a-option v-for="item in filters" :key="item.id" :value="item.id">{{ item.text }}（{{ item.count }}）</a-option></a-select></a-modal>
  </section>
</template>
